import{auth,db}from"./firebase.js";import{api}from"./api.js";import{forgeXModal}from"./utils.js";import{refreshAndSyncCurrentUser,requiresEmailVerification}from"./auth-utils.js";import{onAuthStateChanged,signOut}from"https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";import{doc,getDoc}from"https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";async function loadUserProfile(e){const t=doc(db,"users",e.uid);try{const o=await getDoc(t);if(!o.exists())return;const a=o.data();document.getElementById("prof-name").innerText=a.fullname||"Nem biztosított",document.getElementById("prof-email").innerText=a.email||e.email,document.getElementById("prof-phone").innerText=a.phone||"Nem biztosított"}catch(e){console.error("\nHiba a felhasználói profil adatainak betöltésekor:",e)}}async function loadUserBookings(e){const t=document.getElementById("user-bookings");if(t)try{const o=await api.getBookings(e);if(!o.length)return void(t.innerHTML="<p>Nincsenek aktív foglalásai.</p>");t.innerHTML="",o.forEach(e=>{const o=document.createElement("div");o.className="booking-item",o.innerHTML=`\n                <div class="booking-info">\n                    <p><strong>${e.course}</strong></p>\n                    <p>${e.trainer} - ${e.date} ${e.time}</p>\n                </div>\n                <button class="delete-booking-btn" data-id="${e.id}">\n                    <i class="fa-solid fa-trash"></i>\n                </button>\n            `,t.appendChild(o)}),attachDeleteBookingHandlers(e)}catch(e){console.error("Hiba a foglalások betöltése során:",e),t.innerHTML="<p>Failed to load bookings.</p>"}}function attachDeleteBookingHandlers(e){document.querySelectorAll(".delete-booking-btn").forEach(t=>{t.addEventListener("click",async t=>{const o=t.currentTarget.getAttribute("data-id");await forgeXModal("Megerősítés törlése","Biztosan törölni szeretné ezt a foglalást?",!0)&&(auth.currentUser?await deleteBooking(o,e):console.error("A felhasználó nem lett hitelesítve a törlés során."))})})}async function deleteBooking(e,t){try{await api.deleteBooking(t,e),console.log("Foglalás törölve:",e),loadUserBookings(t)}catch(e){console.error("Hiba a foglalás törlésekor:",e),await forgeXModal("Sikertelen törlés","\nNem tudtuk törölni ezt a foglalást. Kérjük, próbálja meg később.")}}onAuthStateChanged(auth,async e=>{if(e){if(e=await refreshAndSyncCurrentUser()||e,requiresEmailVerification(e))return await forgeXModal("E-mail ellenőrzés szükséges","Kérjük, ellenőrizze az e-mail címét a profil megnyitása előtt."),await signOut(auth),void window.location.replace("signIn.html");console.log("Profile page – authenticated user:",e.uid),await loadUserProfile(e),loadUserBookings(e)}else window.location.replace("signIn.html")});const logoutButton=document.getElementById("logout-btn");logoutButton&&logoutButton.addEventListener("click",async()=>{await forgeXModal("Kijelentkezés","Ha most kijelentkezik, a kosarában és a kedvencekben lévő tételek törlődnek. Ha később ugyanabba a fiókba jelentkezik be, fiókadatai továbbra is elérhetők lesznek.",!0)&&(await signOut(auth),localStorage.removeItem("cart"),localStorage.removeItem("favorites"),window.location.replace("index.html"))});